'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isUint64 = require( '@stdlib/assert/is-uint64' );
var add = require( '@stdlib/number/uint64/base/add' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Uint64Array = require( './../lib' );


// MAIN //

bench( format( '%s:reduceRight', pkg ), function benchmark( b ) {
	var out;
	var arr;
	var i;

	arr = new Uint64Array( 10 );

	// Benchmark worst case scenario (i.e., every element is visited and passed to the reducer)...
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.reduceRight( add );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isUint64( out ) ) {
		b.fail( 'should return a 64-bit unsigned integer' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::initial_value:reduceRight', pkg ), function benchmark( b ) {
	var out;
	var arr;
	var v;
	var i;

	arr = new Uint64Array( 10 );

	v = new Uint64( 0 );

	// Benchmark worst case scenario (i.e., every element is visited and passed to the reducer)...
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.reduceRight( add, v );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isUint64( out ) ) {
		b.fail( 'should return a 64-bit unsigned integer' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
